    async def test_EMS1_5764_5775_5786_qosPrfAdd(self):
        if self.exeServiceGe == "": return
        deleteGeServiceWithProfile (self, "$py_TempQos")
        deleteServiceWithPort (self, self.dutIp, self.geInfo)
        waitGeUpdate (self, self.dutIp, self.geInfo, "Disable")
        deleteFileIfExisted(self,"GE Template","$py_TempQos")
        deleteAutoMaxFileIfTableFull(self,"GE Template",3000)
        deleteFileIfExisted(self,"Weight Profile","$py_Weight")
        deleteAutoMaxFileIfTableFull(self,"Weight Profile",3000)
        deleteFileIfExisted(self,"Shaping Profile","$py_Shaping")
        deleteAutoMaxFileIfTableFull(self,"Shaping Profile",3000)
        deleteFileIfExisted(self,"Rate Limit Profile","$py_RateLimit")
        deleteAutoMaxFileIfTableFull(self,"Rate Limit Profile",3000)
        #Create Weight profile: "$py_Weight"
        createProfile (self, "Weight Profile", "$py_Weight")
        for i in range(8):
            ind = str(i)
            self.driver.find_element(By.ID, "ge_weight_queue" + ind + "_text").send_keys(Keys.CONTROL + "a")
            self.driver.find_element(By.ID, "ge_weight_queue" + ind + "_text").send_keys(Keys.DELETE)
            self.driver.find_element(By.ID, "ge_weight_queue" + ind + "_text").send_keys(ind)
        saveProfile (self)
        #Create Shaping Profile: "$py_Shaping"
        createProfile (self, "Shaping Profile", "$py_Shaping")
        for i in range(8):
            ind = str(i)
            self.driver.find_element(By.ID, "ge_shaping_queue" + ind + "_text").send_keys(Keys.CONTROL + "a")
            self.driver.find_element(By.ID, "ge_shaping_queue" + ind + "_text").send_keys(Keys.DELETE)
            self.driver.find_element(By.ID, "ge_shaping_queue" + ind + "_text").send_keys(str(i*1000000))
        saveProfile (self)
